typedef float vm_num_t;

extern float __fsqrt(float);

class vm_stack {
public:
  int salloc;
  char *buffer;
  char *SP;
  char *get_SP() const { return SP; }
  void pop(int n) { SP += -n; }
  bool push(const char *, int);
};

struct vector3d {
  float x;
  float y;
  float z;
  float length() const { return (float)__fsqrt(x*x + y*y + z*z); }
};

class script_library_class {
public:
  class function {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
  };
};

class slf_vector3d_length_t {
public:
  struct parms_t {
    vector3d me;
  };
  bool operator()(vm_stack& stack, script_library_class::function::entry_t entry);
};

bool slf_vector3d_length_t::operator()(vm_stack& stack, script_library_class::function::entry_t entry)
{
  stack.pop(sizeof(parms_t));
  parms_t* parms = (parms_t*)stack.get_SP();
  vm_num_t result = parms->me.length();
  if (!stack.push((char*)&result,sizeof(result)) )
    error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() );
  return true;
}
